// English / French. The interface is written in English and looked up here; the server's game log,
// cards and chaos events stay English on the wire and are translated on arrival, sentence by sentence.
// Place names (tiles, teams, decks) are proper nouns and are never translated.
const pick = () => { try { const l = localStorage.getItem('mono.lang'); if (l === 'en' || l === 'fr') return l; } catch {} return /^fr/i.test(navigator.language || '') ? 'fr' : 'en'; };
export let lang = pick();
const listeners = [];
export function setLang(l) {
  lang = l === 'fr' ? 'fr' : 'en';
  try { localStorage.setItem('mono.lang', lang); } catch {}
  document.documentElement.lang = lang;
  applyStatic();
  listeners.forEach(f => f());
}
export const onLang = f => listeners.push(f);

