// UI text: t('Buy for {price}', { price: '$200' })
export function t(s, vars) {
  let out = lang === 'fr' && FR[s] != null ? FR[s] : s;
  if (vars) out = out.replace(/\{(\w+)\}/g, (m, k) => (vars[k] != null ? vars[k] : m));
  return out;
}

